void dei_ss_disarm( void *remote )
{		
	if( get_ss_panic()  )
	{
		dei_siren_chirp( DEI_SIREN_STOP );
		return ;	   
	}

	// If human is driving don't do anything
	if( !get_ss_arm() && get_ign_status() && !get_rs_gwr() && !get_ss_trigger() ) return ;
	
	dei_ss_trigger_stop();
	dei_ss_disarm_actions( DEI_SS_NO_SILENT , remote );
}

//--------------------------------------------------------------------------//

void dei_ss_disarm_oem( void *pld )
{
	if( get_ss_panic()  )  
	{
		dei_siren_chirp( DEI_SIREN_STOP );
		return ;	   
	}

	dei_ss_trigger_stop();
			
	dei_ss_disarm_actions( (Dei_Ss_Silent)*cmd_get_pld(pld) , NULL );
}

